RL("level up action","kgm-0909E-r229","    window.kgmCrewUpdateR928=function(){","    /* 1009B：職級晉升（level up）—— 核准後第 30 天生效，生效日起重新排班；已公布的班表照樣凍結，只有當事人從生效日起重排，有異動的組員都通知 */\n    var LVNX9B={FO:'CP',CR:'CP',FA:'DPU',DPU:'PU'},LVZH9B={CP:'正機師',FO:'副機師',CR:'巡航機師',PU:'座艙長',DPU:'副座艙長',FA:'空服員',TRI:'教官資格'};\n    function E9b(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}\n    function lvNext9B(id){var f=window.kgmCrewLevelOfR1009B&&window.kgmCrewLevelOfR1009B(id,'9999-12-31');if(!f)return null;var nx=f.rank==='CP'?(f.tri?null:'TRI'):LVNX9B[f.rank];return nx?{from:f.rank==='CP'&&nx==='TRI'?'CP':f.rank,to:nx,role:f.role}:null}\n    function lvCan9B(){try{if((S.adminUser||{}).role==='ceo')return true;return !!(window.kgmPermR123&&window.kgmPermR123('sched')==='use')}catch(_){return false}}\n    window.kgmLevelUpBtnR1009B=function(id){\n      try{if(!(S.staff||[]).some(function(s){return s&&s.empId===id}))return '';\n        var L=((S.crewLevelR1009B||{})[id]||[]),t=todayISO(),pend=L.filter(function(x){return x&&x.eff>t}),nx=lvNext9B(id);\n        var h='<span class=\"k9b-lv\" style=\"display:inline-flex;gap:8px;align-items:center;margin-left:12px;flex-wrap:wrap;vertical-align:middle\">';\n        pend.forEach(function(x){h+='<em style=\"font-style:normal;font-size:12px;padding:3px 10px;border-radius:999px;background:#fff4dc;color:#7a5200;border:1px solid #f0d9a6\">'\n          +(Z()?'已核准晉升：':'Promotion approved: ')+E9b(LVZH9B[x.from]||x.from)+' → '+E9b(LVZH9B[x.to]||x.to)+(Z()?'（'+x.eff+' 生效，生效日起重新排班）':' (effective '+x.eff+')')+'</em>'});\n        if(nx&&lvCan9B())h+='<button class=\"btn btn-sm\"'+(S._crBusy928?' disabled':'')+' onclick=\"kgmLevelUpR1009B(\\''+E9b(id)+'\\')\">'+(Z()?'升等：':'Level up: ')+E9b(LVZH9B[nx.from]||nx.from)+' → '+E9b(LVZH9B[nx.to]||nx.to)+'</button>';\n        return h+'</span>'}catch(_){return ''}};\n    window.kgmLevelUpR1009B=function(id,silent){\n      var nx=lvNext9B(id),st=(S.staff||[]).filter(function(s){return s&&s.empId===id})[0];if(!nx||!st||!lvCan9B())return false;\n      var eff=AD(todayISO(),30),fz=LVZH9B[nx.from]||nx.from,tz=LVZH9B[nx.to]||nx.to;\n      if(!silent&&!confirm(Z()?(st.name+'（'+id+'）'+fz+' → '+tz+'\\n核准後第 30 天（'+eff+'）生效，生效日起依新職級重新排班；生效日前的班表不變。\\n確定核准？'):('Promote '+st.name+' to '+nx.to+' effective '+eff+'?')))return false;\n      var ex={};ex[id]=eff;\n      window.kgmCrewReplanR928({from:todayISO(),to:AD(eff,13),exclude:ex,   /* 從今天起全部凍結（生效日前的班表不動），只有當事人從生效日起重排 */\n        reason:(Z()?'職級晉升 ':'Promotion ')+st.name+' '+fz+' → '+tz+'（'+eff+' 生效）',\n        apply:function(){S.crewLevelR1009B=S.crewLevelR1009B||{};(S.crewLevelR1009B[id]=S.crewLevelR1009B[id]||[]).push({from:nx.from,to:nx.to,at:new Date().toISOString(),eff:eff,by:(S.adminUser||{}).empId||''})},\n        done:function(rec){try{notifyStaff(id,'【職級晉升】'+fz+' → '+tz+'，'+eff+' 生效；生效日起依新職級排班。')}catch(_){}\n          S._crMsg928=(Z()?'✓ '+st.name+' 晉升「'+tz+'」已核准（'+eff+' 生效）：生效日起重新排班，'+rec.n+' 位組員班表有異動並已通知。':'Promotion approved; '+rec.n+' rosters changed.')}});\n      return true;\n    };\n    window.kgmCrewUpdateR928=function(){",1);
